def geometry_points(coords):
    if len(coords) >= 2 and isinstance(coords[0], (float, int)):
        yield coords[:2]
    else:
        for part in coords:
            yield from geometry_points(part)


def fit_map_points(points, width=800, height=430):
    """Fit longitude/latitude bounds in Web Mercator, with a 15% margin."""
    import math
    points = [(float(x), float(y)) for x, y in points if pd.notna(x) and pd.notna(y)]
    if not points:
        return pdk.ViewState(latitude=30.5, longitude=-89, zoom=4, pitch=0)
    xs = [(x + 180) / 360 for x, _ in points]
    def mercator_y(lat):
        lat = math.radians(max(-85, min(85, lat)))
        return (1 - math.asinh(math.tan(lat)) / math.pi) / 2
    ys = [mercator_y(y) for _, y in points]
    cx, cy = (min(xs)+max(xs))/2, (min(ys)+max(ys))/2
    dx, dy = max(xs)-min(xs), max(ys)-min(ys)
    zoom = 9 if max(dx,dy) < 1e-8 else min(
        math.log2(width/(512*max(dx,1e-8)*1.3)),
        math.log2(height/(512*max(dy,1e-8)*1.3)))
    return pdk.ViewState(longitude=cx*360-180,
        latitude=math.degrees(math.atan(math.sinh(math.pi*(1-2*cy)))),
        zoom=max(2,min(10,zoom)), pitch=0)


def themed_dataframe(data, **kwargs):
    """Theme-aware read-only table with search, sorting, CSV and column controls."""
    import html
    frame = pd.DataFrame(data).copy()
    for col in frame:
        if pd.api.types.is_datetime64_any_dtype(frame[col]):
            frame[col] = frame[col].dt.strftime("%Y-%m-%d")
    headers = [str(c) for c in frame.columns]
    rows = json.loads(frame.to_json(orient="values", date_format="iso"))
    payload = json.dumps({"headers":headers, "rows":rows}, ensure_ascii=True).replace('<','\\u003c')
    csv_data = base64.b64encode(frame.to_csv(index=False).encode()).decode()
    template = r'''<!doctype html><html><head><meta charset="utf-8"><style>
    *{box-sizing:border-box}body{margin:0;font:14px system-ui,sans-serif;color:__FG__;background:__BG__}
    .tools{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:0 0 8px}
    button,a,summary,input{font:inherit;color:__FG__;background:__PANEL__;border:1px solid __LINE__;border-radius:6px;padding:7px 10px}
    input{flex:1;min-width:140px}a{text-decoration:none}button,summary{cursor:pointer}button:hover,a:hover{border-color:__ACCENT__}
    details{position:relative}details>div{position:absolute;right:0;top:38px;background:__PANEL__;padding:10px;border:1px solid __LINE__;border-radius:6px;z-index:5;min-width:230px;max-height:200px;overflow:auto}
    details label{display:block;padding:4px}details input{min-width:0}
    .wrap{overflow:auto;max-height:390px;border:1px solid __LINE__;border-radius:10px;background:__PANEL__}
    table{border-collapse:collapse;width:100%;white-space:nowrap}th,td{padding:10px 13px;text-align:left;border-bottom:1px solid __LINE__;border-right:1px solid __LINE__}
    th{position:sticky;top:0;background:__BG__;color:__FG__;cursor:pointer;font-weight:600;z-index:1;max-width:270px;white-space:normal}
    td{background:__PANEL__}tr:nth-child(even) td{background:__BG__}td.num{text-align:right;font-variant-numeric:tabular-nums}
    #status{color:__DIM__;font-size:12px;margin:6px 0}body:fullscreen{padding:16px}.wrap:fullscreen{max-height:none}
    </style></head><body><div class="tools"><input id="search" type="search" placeholder="Search this table…" aria-label="Search this table">
    <details><summary>Columns</summary><div id="columns"></div></details>
    <a download="climate_data.csv" href="data:text/csv;base64,__CSV__">Download CSV</a><button id="expand">Fullscreen</button></div>
    <div class="wrap"><table><thead></thead><tbody></tbody></table></div><div id="status" aria-live="polite"></div>
    <script>const data=__DATA__;let order=-1,asc=true;const hidden=new Set();
    const cellText=(v,i)=>typeof v==='number'?(/year|fips/i.test(data.headers[i])?String(v):v.toLocaleString('en-US',{maximumFractionDigits:4})):String(v??'—');
    const elem=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e};
    function render(){let rows=data.rows.filter(r=>r.some((v,i)=>(String(v??'')+' '+cellText(v,i)).toLowerCase().includes(document.querySelector('#search').value.toLowerCase())));
    if(order>=0)rows.sort((a,b)=>{const x=a[order],y=b[order];return(asc?1:-1)*(typeof x==='number'&&typeof y==='number'?x-y:String(x??'').localeCompare(String(y??''),undefined,{numeric:true}))});
    const head=document.querySelector('thead'),body=document.querySelector('tbody');head.replaceChildren();body.replaceChildren();const tr=elem('tr','');
    data.headers.forEach((h,i)=>{if(hidden.has(i))return;const th=elem('th',h+(order===i?(asc?' ↑':' ↓'):''));th.tabIndex=0;th.setAttribute('aria-sort',order===i?(asc?'ascending':'descending'):'none');const sort=()=>{asc=order===i?!asc:true;order=i;render()};th.onclick=sort;th.onkeydown=e=>{if(e.key==='Enter')sort()};tr.append(th)});head.append(tr);
    for(const row of rows){const tr=elem('tr','');row.forEach((v,i)=>{if(hidden.has(i))return;const text=cellText(v,i);const td=elem('td',text);if(typeof v==='number')td.className='num';tr.append(td)});body.append(tr)}
    document.querySelector('#status').textContent=rows.length+' of '+data.rows.length+' rows · Click a heading to sort.'}
    data.headers.forEach((h,i)=>{const label=elem('label',''),check=elem('input','');check.type='checkbox';check.checked=true;check.onchange=()=>{check.checked?hidden.delete(i):hidden.add(i);render()};label.append(check,document.createTextNode(' '+h));document.querySelector('#columns').append(label)});
    document.querySelector('#search').oninput=render;
    document.querySelector('#expand').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){document.querySelector('#status').textContent='Fullscreen is unavailable in this browser. Use the horizontal scrollbar to see more columns.'}};
    render();</script></body></html>'''
    for token, value in {"__FG__":palette["fg"], "__BG__":palette["bg"], "__PANEL__":palette["panel"],
        "__LINE__":palette["line"], "__DIM__":palette["dim"], "__ACCENT__":palette["accent"],
        "__CSV__":csv_data, "__DATA__":payload}.items():
        template = template.replace(token, value)
    components.html(template, height=min(495, 135 + 42 * (len(frame)+1)), scrolling=False)

def style_weather_chart(chart):
    """Use the companion dashboard's palette without changing calculations."""
    chart.update_layout(
        template="plotly_dark" if dark else "plotly_white",
        paper_bgcolor=palette["panel"], plot_bgcolor=palette["panel"],
        font=dict(color=palette["fg"], family="Arial, sans-serif"),
        margin=dict(l=24, r=24, t=65, b=35), hovermode="x unified",
        hoverlabel=dict(bgcolor=palette["panel"], font_color=palette["fg"]),
        legend=dict(font=dict(color=palette["fg"])),
    )
    chart.update_xaxes(gridcolor=palette["line"], tickfont=dict(color=palette["fg"]), title_font=dict(color=palette["fg"]))
    chart.update_yaxes(gridcolor=palette["line"], tickfont=dict(color=palette["fg"]), title_font=dict(color=palette["fg"]))
    return chart


