_NATIONAL_MAP_GZIP = ''


@st.cache_data
def load_national_map():
    return json.loads(gzip.decompress(base64.b64decode(_NATIONAL_MAP_GZIP)))


def render_national_explorer():
    geo = load_national_map()
    names = geo["names"]
    st.subheader("Explore U.S. counties")
    st.caption("Lower 48 states and Washington, D.C. • Select a state and county to explore")
    a, b = st.columns(2)
    region = a.selectbox("Map state", ["All mapped states"] + sorted({n[1] for n in names.values()}), key="national_state")
    available = sorted(
        [f for f, n in names.items() if region == "All mapped states" or n[1] == region],
        key=lambda f: (names[f][1], names[f][0]),
    )
    chosen = b.selectbox(
        "Map county", [""] + available,
        format_func=lambda f: "Choose a county" if not f else f"{names[f][0]}, {names[f][1]} ({f})",
        key=f"national_county_{region}",
    )
    left, middle, right = st.columns(3)
    left.metric("Counties in selected area", f"{len(available):,}")
    middle.metric("Selected county", names[chosen][0] if chosen else "Choose a county")
    right.metric("County FIPS", chosen or "—")
    fill = "#303b4d" if dark else "#dfe3e9"
    edge = "#8290a5" if dark else "#66758b"
    map_extent = st.radio(
        "Map view", ["National overview", "Selected state"], horizontal=True,
        key="county_map_extent",
        help="The national overview keeps the full map visible while you select a county.",
    )
    mapped = sorted(names) if map_extent == "National overview" else available
    parts = []
    # Draw selection last so its outline is never covered by a neighbouring county.
    ordered = [f for f in mapped if f != chosen] + ([chosen] if chosen else [])
    for f in ordered:
        name = f"{names[f][0]}, {names[f][1]} • FIPS {f} • Predictions not connected"
        colour = palette["accent"] if f == chosen else fill
        stroke = "#ffc147" if f == chosen else edge
        width = "2" if f == chosen else "0.45"
        parts.append(
            f'<path d="{escape(geo["counties"][f], quote=True)}" fill="{colour}" '
            f'stroke="{stroke}" stroke-width="{width}" vector-effect="non-scaling-stroke">'
            f'<title>{escape(name)}</title></path>'
        )
    document = f"""<!doctype html><html><head><meta charset="utf-8">
    <style>body{{margin:0;background:{palette['panel']};color:{palette['fg']};font-family:Arial,sans-serif}}
    svg{{width:100%;height:560px;display:block}}path:hover{{fill:{palette['accent']};cursor:help}}
    p{{margin:8px 16px;font-size:13px;color:{palette['dim']}}} </style></head>
    <body><svg id="county-map" viewBox="0 0 {geo['width']} {geo['height']}" role="img"
    aria-label="County boundaries; no risk predictions"><g id="county-shapes">{''.join(parts)}</g></svg>
    <p>Hover for county details. Use the selectors above to change the selected county.
    Blue fill and gold outline indicate selection, not risk.</p>
    <script>
    const shape=document.getElementById('county-shapes');
    const box=shape.getBBox();
    if(box.width>0 && box.height>0){{
      const pad=Math.max(box.width,box.height)*0.04;
      document.getElementById('county-map').setAttribute('viewBox',
        [box.x-pad,box.y-pad,box.width+2*pad,box.height+2*pad].join(' '));
    }}
    </script></body></html>"""
    components.html(document, height=625, scrolling=False)
    st.caption("Risk colours are not shown because model predictions are not connected in this version.")
    st.caption("Coverage: lower 48 states and Washington, D.C. Alaska, Hawaii and territories are not included. The supplied boundary file includes some older county definitions.")
    with st.expander("Browse counties in this area"):
        themed_dataframe(pd.DataFrame([
            {"County": names[f][0], "State": names[f][1], "FIPS": f}
            for f in available
        ]), hide_index=True, width="stretch")


