# Fixed sites from 02_eda_gulf_coast.ipynb; observations come from the processed file.
EDA_COMPARISON_STATIONS = {
    "USW00012960": "Houston, TX",
    "USW00012916": "New Orleans, LA",
    "USW00013894": "Mobile, AL",
    "USW00013865": "Meridian, MS",
    "USW00012842": "Tampa, FL",
}


@st.cache_data(max_entries=4)
def load_comparison_rainfall(file_path, file_version):
    """Read five stations only; processed values are already millimeters."""
    return pd.read_parquet(
        file_path, engine="pyarrow", columns=["STATION", "DATE", "PRCP"],
        filters=[("STATION", "in", list(EDA_COMPARISON_STATIONS))],
    )


def clean_comparison_rainfall(data):
    """Validate station-days and rainfall before determining usable comparison years."""
    daily = data.loc[data["STATION"].isin(EDA_COMPARISON_STATIONS), ["STATION", "DATE", "PRCP"]].copy()
    daily["DATE"] = pd.to_datetime(daily["DATE"], errors="raise").dt.normalize()
    if daily["DATE"].isna().any() or daily.duplicated(["STATION", "DATE"]).any():
        raise ValueError("Comparison stations contain missing or duplicate station/date records.")
    daily["PRCP"] = pd.to_numeric(daily["PRCP"], errors="raise")
    daily.loc[(daily["PRCP"] < 0) | daily["PRCP"].isin([float("inf"), -float("inf")]), "PRCP"] = float("nan")
    daily["Year"] = daily["DATE"].dt.year
    daily["Month"] = daily["DATE"].dt.month
    return daily


def comparison_year_bounds(data, last_closed_year):
    """First/last years meeting the annual requirement at all five stations."""
    daily = clean_comparison_rainfall(data)
    daily = daily.loc[daily["Year"] <= last_closed_year]
    if daily.empty:
        return None
    counts = daily.groupby(["Year", "STATION"])["PRCP"].count().unstack("STATION")
    counts = counts.reindex(columns=list(EDA_COMPARISON_STATIONS)).fillna(0)
    years = counts.index[counts.ge(MIN_VALID_DAYS).all(axis=1)]
    return (int(years.min()), int(years.max())) if len(years) else None


def decade_period_label(first_year, last_year):
    return f"{int(first_year)} only" if first_year == last_year else f"{int(first_year)}–{int(last_year)}"


def station_comparison_summaries(data, start_year, end_year):
    """Compare the same qualifying calendar years, without filling missing rain."""
    daily = clean_comparison_rainfall(data)
    daily = daily.loc[daily["Year"].between(start_year, end_year)].copy()
    grid = pd.MultiIndex.from_product(
        [list(EDA_COMPARISON_STATIONS), range(start_year, end_year + 1)], names=["STATION", "Year"],
    )
    counts = daily.groupby(["STATION", "Year"])["PRCP"].count().reindex(grid, fill_value=0)
    wide = counts.unstack("STATION")
    common_years = wide.index[wide.ge(MIN_VALID_DAYS).all(axis=1)].tolist()
    coverage = counts.rename("Valid rainfall days").reset_index()
    coverage["Station"] = coverage["STATION"].map(EDA_COMPARISON_STATIONS)
    coverage["Calendar days"] = coverage["Year"].map(lambda y: 366 if isleap(y) else 365)
    coverage["Coverage (%)"] = 100 * coverage["Valid rainfall days"] / coverage["Calendar days"]
    coverage["Used in comparison"] = coverage["Year"].isin(common_years)
    result = {"coverage": coverage, "years": common_years}
    if not common_years:
        return result
    included = daily.loc[daily["Year"].isin(common_years)].copy()
    included["Station"] = included["STATION"].map(EDA_COMPARISON_STATIONS)
    included["Heavy rain days"] = included["PRCP"].ge(50) & included["PRCP"].notna()
    annual = included.groupby(["Station", "Year"], as_index=False).agg(
        **{"Rainfall total (mm)": ("PRCP", lambda s: s.sum(min_count=1)),
           "Heavy rain days": ("Heavy rain days", "sum"), "Valid rainfall days": ("PRCP", "count")}
    )
    summary = annual.groupby("Station", as_index=False).agg(
        **{"Mean annual observed rainfall (mm)": ("Rainfall total (mm)", "mean"),
           "Heavy rain days": ("Heavy rain days", "sum"),
           "Valid rainfall days": ("Valid rainfall days", "sum"), "Shared years": ("Year", "count")}
    )
    summary["Heavy rain (% of observed days)"] = 100 * summary["Heavy rain days"] / summary["Valid rainfall days"]
    monthly = included.groupby(["Station", "Year", "Month"])["PRCP"].agg(["count", "mean"]).reset_index()
    month_grid = pd.MultiIndex.from_product(
        [list(EDA_COMPARISON_STATIONS.values()), common_years, range(1, 13)], names=["Station", "Year", "Month"],
    )
    monthly = monthly.set_index(["Station", "Year", "Month"]).reindex(month_grid).reset_index()
    calendar_days = pd.to_datetime(dict(year=monthly["Year"], month=monthly["Month"], day=1)).dt.days_in_month
    monthly["Eligible"] = monthly["count"].ge(0.8 * calendar_days)
    # A month/year contributes only if all five stations meet its coverage requirement.
    common_month = monthly.groupby(["Year", "Month"])["Eligible"].transform("all")
    seasonal = monthly.loc[common_month].groupby(["Station", "Month"]).agg(
        **{"Average daily rainfall (mm)": ("mean", "mean"), "Shared month-years": ("Year", "count")}
    ).reindex(pd.MultiIndex.from_product(
        [list(EDA_COMPARISON_STATIONS.values()), range(1, 13)], names=["Station", "Month"],
    )).reset_index()
    seasonal["Shared month-years"] = seasonal["Shared month-years"].fillna(0).astype(int)
    seasonal["Month name"] = pd.to_datetime(seasonal["Month"], format="%m").dt.strftime("%b")
    top_days = included.dropna(subset=["PRCP"]).sort_values(
        ["PRCP", "DATE", "STATION"], ascending=[False, True, True],
    ).head(10)[["Station", "STATION", "DATE", "PRCP"]].rename(columns={"PRCP": "Rainfall (mm)"})
    regional = annual.groupby("Year", as_index=False).agg(
        **{"Heavy-rain station-days": ("Heavy rain days", "sum"),
           "Observed station-days": ("Valid rainfall days", "sum")}
    )
    # Preserve excluded years as gaps, even when their heavy-rain count would be zero.
    regional = regional.set_index("Year").reindex(pd.Index(range(start_year, end_year + 1), name="Year")).reset_index()
    annual["Decade"] = (annual["Year"] // 10) * 10
    decades = annual.groupby("Decade", as_index=False).agg(
        **{"Heavy-rain station-days": ("Heavy rain days", "sum"),
           "Observed station-days": ("Valid rainfall days", "sum"),
           "Shared years": ("Year", "nunique"), "Station-years": ("Year", "count"),
           "First shared year": ("Year", "min"), "Last shared year": ("Year", "max")}
    )
    decades["Heavy-rain days per 1,000 observed station-days"] = 1000 * decades["Heavy-rain station-days"] / decades["Observed station-days"]
    decades["Mean heavy-rain days per station-year"] = decades["Heavy-rain station-days"] / decades["Station-years"]
    result.update(summary=summary, seasonal=seasonal, top_days=top_days, regional=regional, decades=decades, annual=annual)
    return result


def render_station_comparisons(file_info):
    st.subheader("Five-station rainfall comparison")
    st.caption(
        "Adapted from 02_eda_gulf_coast.ipynb: Houston, New Orleans, Mobile, Meridian and Tampa. "
        "Source: processed NOAA dataset; the original sample file is not used. These five stations "
        "illustrate local weather and do not represent whole states. This section uses its own "
        "year range; sidebar state, county, station and year selections do not change it."
    )
    with st.expander("Compare five stations: rainfall, heavy rain and wettest days", expanded=False):
        enabled = st.checkbox("Load five-station comparison", key="load_five_station_comparison", value=False)
        if not enabled:
            st.caption("Enable this to load records for the five comparison stations.")
            return
        last_closed_year = pd.Timestamp.now(tz="UTC").year - 1
        try:
            with st.spinner("Loading comparison observations…"):
                raw = load_comparison_rainfall(str(WEATHER_FILE), (file_info.st_mtime_ns, file_info.st_size))
                bounds = comparison_year_bounds(raw, last_closed_year)
            if bounds is None:
                st.info("No completed years meet the 330-day rainfall requirement at all five stations in this dataset. A shared comparison period is unavailable.")
                return
            first_year, last_year = bounds
            if first_year == last_year:
                period = bounds
                st.caption(f"Only one shared qualifying year is available: {first_year}.")
            else:
                default_start, default_end = max(1991, first_year), min(2020, last_year)
                if default_start > default_end:
                    default_start, default_end = bounds
                period = st.slider(
                    "Comparison year range", min_value=first_year, max_value=last_year,
                    value=(default_start, default_end), key=f"five_station_years_{first_year}_{last_year}",
                    help="Limits follow the first and last shared qualifying years in this dataset. Years within that range still need 330 valid rainfall days at every station.",
                )
            with st.spinner("Preparing rainfall comparisons…"):
                results = station_comparison_summaries(raw, *period)
        except (ValueError, OSError, KeyError, TypeError) as error:
            st.warning(f"Five-station comparison unavailable: {error}")
            return
        years = results["years"]
        st.caption(
            f"Requested period: {period[0]}–{period[1]}. Shared qualifying years: {len(years)}. "
            "A year is used only when every station has at least 330 valid rainfall observations. "
            "Current year excluded. Gaps remain missing; totals cover observed days only. "
            "Heavy rain means at least 50 mm at a station, not an observed flood."
        )
        with st.expander("View shared years and station coverage"):
            st.write("Shared years: " + (", ".join(map(str, years)) if years else "None"))
            themed_dataframe(results["coverage"].drop(columns="STATION"), hide_index=True, width="stretch")
        if not years:
            st.info("No shared years meet the rainfall requirement for all five stations. Try a different comparison range; the coverage table identifies missing stations or years.")
            return
        summary = results["summary"]
        annual_chart = px.bar(
            summary.sort_values("Mean annual observed rainfall (mm)"),
            x="Mean annual observed rainfall (mm)", y="Station", orientation="h",
            hover_data={"Shared years": True, "Valid rainfall days": True},
            title="Mean Annual Rainfall Across Five Stations (Observed Days)",
            color_discrete_sequence=[palette["accent"]],
        )
        st.plotly_chart(style_weather_chart(annual_chart), width="stretch")
        st.caption("Each value is the equal-weight mean of annual observed totals over the same shared years; it is not a daily average multiplied by 365.")
        seasonal = results["seasonal"]
        if seasonal["Average daily rainfall (mm)"].notna().any():
            fig = px.line(
                seasonal, x="Month name", y="Average daily rainfall (mm)", color="Station", markers=True,
                hover_data={"Shared month-years": True, "Month": False},
                title="Seasonal Rainfall Across Five Stations", labels={"Month name": "Month"},
            )
            fig.update_traces(connectgaps=False)
            st.plotly_chart(style_weather_chart(fig), width="stretch")
        else:
            st.info("No month-years meet the common monthly coverage requirement.")
        st.caption("For each month, only shared years with at least 80% of calendar days observed at every station contribute. Month-year daily means receive equal weight. Different months may use different shared years; hover for the count.")
        st.markdown("**Heavy rain by station**")
        fig = px.bar(
            summary, x="Station", y="Heavy rain (% of observed days)",
            hover_data={"Heavy rain days": True, "Valid rainfall days": True, "Shared years": True},
            title="Heavy-Rain Frequency Across Five Stations", color_discrete_sequence=[palette["accent"]],
        )
        st.plotly_chart(style_weather_chart(fig), width="stretch")
        themed_dataframe(summary[["Station", "Heavy rain days", "Valid rainfall days", "Heavy rain (% of observed days)", "Shared years"]], hide_index=True, width="stretch")
        st.markdown("**Top 10 wettest observed station-days**")
        st.caption("Ranks the five comparison stations within shared qualifying years in the chosen period. This is not a ranking of all 523 stations or all-time records. The same storm can appear at multiple stations.")
