        themed_dataframe(decades[["Years represented", "Shared years", "Heavy-rain station-days", "Observed station-days", "Station-years", "Heavy-rain days per 1,000 observed station-days", "Mean heavy-rain days per station-year"]], hide_index=True, width="stretch")


