# County social vulnerability is separate from model hazard predictions.
COUNTY_DATA_DIR = Path(__file__).resolve().parents[1] / "data" / "processed"
SVI_FILES = {
    "scores": "svi_gulf_coast_counties.csv",
    "boundaries": "gulf_coast_counties.geojson",
    "mapping": "station_county_mapping_with_match_method.csv",
}
SVI_COLORS = {
    "Lower": [239, 243, 255, 190],
    "Moderate": [189, 215, 231, 190],
    "Higher": [107, 174, 214, 190],
    "Highest": [33, 113, 181, 210],
    "Unavailable": [140, 140, 140, 150],
}


def svi_band(score):
    if pd.isna(score) or not 0 <= score <= 1:
        return "Unavailable"
    if score < 0.25:
        return "Lower"
    if score < 0.50:
        return "Moderate"
    if score < 0.75:
        return "Higher"
    return "Highest"


@st.cache_data(max_entries=4)
def load_county_vulnerability(directory, versions):
    # versions invalidates the cache when any of the three files changes.
    folder = Path(directory)
    scores = pd.read_csv(folder / SVI_FILES["scores"], dtype={"FIPS": str})
    required = {"FIPS", "COUNTY", "ST_ABBR", "RPL_THEMES"}
    if not required.issubset(scores.columns):
        raise ValueError("SVI file needs FIPS, COUNTY, ST_ABBR and RPL_THEMES columns.")
    if scores.empty or scores["FIPS"].isna().any():
        raise ValueError("SVI file is empty or has missing county IDs.")
    scores["FIPS"] = scores["FIPS"].str.strip().str.zfill(5)
    if not scores["FIPS"].str.fullmatch(r"\d{5}").all() or scores["FIPS"].duplicated().any():
        raise ValueError("SVI county IDs must be unique five-digit FIPS codes.")
    if scores[["COUNTY", "ST_ABBR"]].isna().any().any():
        raise ValueError("SVI file has missing county names or states.")
    scores["RPL_THEMES"] = pd.to_numeric(scores["RPL_THEMES"], errors="coerce")
    # Missing/sentinel scores must never look like low vulnerability.
    scores.loc[~scores["RPL_THEMES"].between(0, 1), "RPL_THEMES"] = float("nan")
    scores["Band"] = scores["RPL_THEMES"].map(svi_band)
    scores = scores.loc[scores["ST_ABBR"].isin(STATE_NAMES)].copy()
    if scores.empty:
        raise ValueError("SVI file has no counties in the supported dataset states.")

    with (folder / SVI_FILES["boundaries"]).open() as handle:
        boundaries = json.load(handle)
    if boundaries.get("type") != "FeatureCollection":
        raise ValueError("County boundaries must be a GeoJSON FeatureCollection.")
    features = {}
    for feature in boundaries.get("features", []):
        props = feature.get("properties") or {}
        fips = str(props.get("GEOID", "")).zfill(5)
        geometry = feature.get("geometry") or {}
        if geometry.get("type") not in ("Polygon", "MultiPolygon"):
            raise ValueError("County boundary geometry must be Polygon or MultiPolygon.")
        if fips in features:
            raise ValueError("County boundaries contain duplicate GEOID values.")
        features[fips] = feature
    absent = set(scores["FIPS"]) - set(features)
    if absent:
        raise ValueError(f"County boundaries are missing {len(absent)} SVI county IDs.")

    mapping = pd.read_csv(
        folder / SVI_FILES["mapping"], dtype={"STATION": str, "county_fips": str}
    )
    if not {"STATION", "county_fips"}.issubset(mapping.columns):
        raise ValueError("Station mapping needs STATION and county_fips columns.")
    if mapping["STATION"].isna().any() or mapping["STATION"].duplicated().any():
        raise ValueError("Station mapping must have unique, nonmissing station IDs.")
    mapping["county_fips"] = mapping["county_fips"].str.strip().str.zfill(5)
    return scores, features, mapping.set_index("STATION")["county_fips"].to_dict()


def county_map_data(scores, features, selected_fips):
    result = []
    for row in scores.itertuples(index=False):
        score = row.RPL_THEMES
        result.append({
            "type": "Feature",
            "geometry": features[row.FIPS]["geometry"],
            "properties": {
                "county": f"{row.COUNTY}, {row.ST_ABBR}",
                "fips": row.FIPS,
                "score": "Unavailable" if pd.isna(score) else f"{score:.4f}",
                "band": row.Band,
                "fill": SVI_COLORS[row.Band],
                "outline": [255, 193, 7, 255] if row.FIPS == selected_fips else [95, 110, 125, 180],
                "line_width": 4 if row.FIPS == selected_fips else 1,
            },
        })
    return {"type": "FeatureCollection", "features": result}


def county_center(geometry):
    # Bounding-box midpoint is used only to center the view, not as a weather location.
    points = []
    def collect(coordinates):
        if coordinates and isinstance(coordinates[0], (int, float)):
            points.append(coordinates[:2])
        else:
            for child in coordinates:
                collect(child)
    collect(geometry["coordinates"])
    if not points:
        raise ValueError("Selected county has no boundary coordinates.")
    longitude = (min(p[0] for p in points) + max(p[0] for p in points)) / 2
    latitude = (min(p[1] for p in points) + max(p[1] for p in points)) / 2
    return latitude, longitude




