WEATHER_FILE = (
    Path(__file__).resolve().parents[1]
    / "data" / "processed" / "gulf_coast_historical.parquet"
)


@st.cache_data(max_entries=32)
def load_weather_data(station_id, file_path, file_version):
    # file_version invalidates cached records when the dataset is replaced.
    data = pd.read_parquet(
        file_path,
        engine="pyarrow",
        columns=["DATE", "TMAX", "PRCP"],
        filters=[("STATION", "==", station_id)],
    )
    if data.empty:
        raise ValueError(f"No processed weather records found for {station_id}.")
    data["DATE"] = pd.to_datetime(data["DATE"], errors="raise")
    if data["DATE"].isna().any() or data["DATE"].duplicated().any():
        raise ValueError("Selected station has missing or duplicate observation dates.")
    for column in ["TMAX", "PRCP"]:
        data[column] = pd.to_numeric(data[column], errors="raise")
    # The processed dataset already stores temperature in °C and rainfall in mm.
    return data.sort_values("DATE").reset_index(drop=True)



MIN_VALID_DAYS = 330


def annual_coverage(data, start_year, end_year):
    """Include absent years and absent dates as missing, including leap days."""
    years = pd.Index(range(start_year, end_year + 1), name="Year")
    counts = data.groupby("Year")[["TMAX", "PRCP"]].count().reindex(years, fill_value=0)
    result = pd.DataFrame(index=years)
    result["Calendar days"] = [366 if isleap(y) else 365 for y in years]
    for variable, label in [("TMAX", "Temperature"), ("PRCP", "Rainfall")]:
        result[f"{label} valid days"] = counts[variable]
        result[f"{label} missing days"] = result["Calendar days"] - counts[variable]
        result[f"{label} coverage (%)"] = (
            100 * counts[variable] / result["Calendar days"]
        ).round(1)
        result[f"{label} status"] = counts[variable].map(
            lambda n: "Included" if n >= MIN_VALID_DAYS else "Excluded: fewer than 330 days"
        )
    return result.reset_index()


def rainfall_eda_summaries(data, start_year, end_year):
    """Coverage-aware station summaries; absent observations never become dry days."""
    daily = data[["DATE", "PRCP"]].copy()
    daily["DATE"] = pd.to_datetime(daily["DATE"])
    daily["PRCP"] = pd.to_numeric(daily["PRCP"], errors="coerce")
    daily.loc[daily["PRCP"] < 0, "PRCP"] = float("nan")
    daily["Year"] = daily["DATE"].dt.year
    daily["Month"] = daily["DATE"].dt.month
    daily = daily.loc[daily["Year"].between(start_year, end_year)]
    counts = daily.groupby("Year")["PRCP"].count()
    qualifying = counts.index[counts >= MIN_VALID_DAYS]
    included = daily.loc[daily["Year"].isin(qualifying)].copy()
    included["Heavy rain days"] = included["PRCP"].ge(50) & included["PRCP"].notna()
    years = pd.Index(range(start_year, end_year + 1), name="Year")
    annual = pd.DataFrame(index=years)
    annual["Valid rainfall days"] = counts.reindex(years, fill_value=0).astype(int)
    annual["Heavy rain days"] = included.groupby("Year")["Heavy rain days"].sum().reindex(years)
    annual["Status"] = annual["Valid rainfall days"].map(
        lambda count: "Included" if count >= MIN_VALID_DAYS else
        ("No observations" if count == 0 else "Excluded: fewer than 330 valid days")
    )
    annual = annual.reset_index()
    monthly = included.groupby(["Year", "Month"])["PRCP"].agg(["count", "mean"]).reset_index()
    if not monthly.empty:
        calendar_days = pd.to_datetime(dict(year=monthly["Year"], month=monthly["Month"], day=1)).dt.days_in_month
        monthly = monthly.loc[monthly["count"] >= 0.8 * calendar_days]
    seasonal = monthly.groupby("Month").agg(
        **{"Average daily rainfall (mm)": ("mean", "mean"), "Contributing years": ("Year", "count")}
    ).reindex(pd.Index(range(1, 13), name="Month")).reset_index()
    seasonal["Contributing years"] = seasonal["Contributing years"].fillna(0).astype(int)
    seasonal["Month name"] = pd.to_datetime(seasonal["Month"], format="%m").dt.strftime("%b")
    return seasonal, annual


def harvey_rainfall_window(data):
    """Fixed Houston case study, independent of the sidebar's station/year filters."""
    daily = data[["DATE", "PRCP"]].copy()
    daily["DATE"] = pd.to_datetime(daily["DATE"])
    daily["PRCP"] = pd.to_numeric(daily["PRCP"], errors="coerce")
    daily.loc[daily["PRCP"] < 0, "PRCP"] = float("nan")
    window = pd.date_range("2017-08-20", "2017-09-05", name="DATE")
    return daily.set_index("DATE").reindex(window).reset_index()



